const today = new Date().toISOString().split('T')[0];
const all = $input.all();

// Filtrar reservas de hoy (excluye canceladas)
const hoy = all.filter(item => {
  const fecha = item.json['Fecha Reserva'] || '';
  const estado = (item.json['Estado'] || '').toLowerCase();
  return fecha === today && estado !== 'cancelado';
});

// Ordenar por hora
hoy.sort((a, b) => (a.json['Hora'] || '').localeCompare(b.json['Hora'] || ''));

const count = hoy.length;
const totalPersonas = hoy.reduce((s, r) => s + (parseInt(r.json['Personas']) || 0), 0);

// Lista detallada de reservas
const lista = count > 0
  ? hoy.map(r => `🕐 ${r.json['Hora']} | 👥 ${r.json['Personas']} pers. | 👤 ${r.json['Nombre']}`).join('\n')
  : 'Sin reservas para hoy';

// Pendientes de confirmar
const pendientes = hoy.filter(r => (r.json['Estado'] || '').toLowerCase() === 'pendiente').length;

const fechaLegible = new Date().toLocaleDateString('es-ES', {
  weekday: 'long', year: 'numeric', month: 'long', day: 'numeric'
});

return [{
  json: {
    tieneReservas: count > 0,
    count,
    totalPersonas,
    pendientes,
    lista,
    fechaLegible,
    today
  }
}];

